func (r *CollectorResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	dec := json.NewDecoder(bytes.NewReader([]byte(req.ID)))
	dec.DisallowUnknownFields()
	var data struct {
		GroupID string `json:"group_id"`
		ID      string `json:"id"`
	}
	if err := dec.Decode(&data); err != nil {
		resp.Diagnostics.AddError("Invalid ID", `The import ID is not valid. It is expected to be a JSON object string with the required path parameters: `+err.Error())
		return
	}
	if data.GroupID == "" {
		resp.Diagnostics.AddError("Missing required field", `The field group_id is required but was not found in the json encoded ID.`)
		return
	}
	if data.ID == "" {
		resp.Diagnostics.AddError("Missing required field", `The field id is required but was not found in the json encoded ID.`)
		return
	}
	var model CollectorModel
	model.GroupID = types.StringValue(data.GroupID)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("group_id"), data.GroupID)...)
	model.ID = types.StringValue(data.ID)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("id"), data.ID)...)
	if resp.Diagnostics.HasError() {
		return
	}
	apiModel, err := r.api.Read(ctx, model)
	if err != nil {
		resp.Diagnostics.AddError("failure to invoke API", err.Error())
		return
	}
	applyCollectorAPIToState(apiModel, &model, true, true)
	resp.Diagnostics.Append(resp.State.Set(ctx, &model)...)
}

func isCollectorImportState(state *CollectorModel) bool {
	if state == nil {
		return false
	}
	// Resources whose bodies contain only optional fields have no required
	// sentinel. An ID-only state is an import and must be hydrated from Read.
	if state.InputCollectorSplunk != nil {
		return false
	}
	if state.InputCollectorRest != nil {
		return false
	}
	if state.InputCollectorS3 != nil {
		return false
	}
	if state.InputCollectorAzureBlob != nil {
		return false
	}
	if state.InputCollectorCriblLake != nil {
		return false
	}
	if state.InputCollectorDatabase != nil {
		return false
	}
	if state.InputCollectorGCS != nil {
		return false
	}
	if state.InputCollectorHealthCheck != nil {
		return false
	}
	if state.InputCollectorScript != nil {
		return false
	}
	if state.InputCollectorFilesystem != nil {
		return false
	}
	return true
}

